#include <cstdio>
#include <vector>
#include <algorithm>

int n;
std::vector<int> t, f;
std::vector<std::vector<int>> edges;

int dfs(int u) {
    if (f[u] != -1) return f[u];
    f[u] = t[u];
    for (int v : edges[u])
        f[u] = std::max(f[u], dfs(v) + t[u]);
    return f[u];
}

int main() {
    std::scanf("%d", &n);
    t.resize(n + 1);
    f.assign(n + 1, -1);
    edges.resize(n + 1);

    for (int i = 1, k; i <= n; ++i) {
        std::scanf("%d%d", &t[i], &k);
        edges[i].resize(k);
        for (int &v : edges[i])
            std::scanf("%d", &v);
    }

    int ans = -2147483647;
    for (int i = 1; i <= n; ++i)
        ans = std::max(ans, dfs(i));

    std::printf("%d", ans);
    return 0;
}

